// Opt-in synthetic E2E metadata only; no real IDs, headers, bodies or errors.
// The one reserved diagnostic ID is generated by the marked synthetic test.
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { HEADER, parseId, assertSyntheticFixture, serverComplete } = require('./anydoc-diagnostic-contract.cjs');
const MAX_RECORDS = 514; // start + 128 requests * four lifecycle events + end
const count = value => Number.isSafeInteger(value) && value >= 0;

function diagnosticMetadata(record) {
  if (record === null || typeof record !== 'object' || Array.isArray(record)) return null;
  const { event, seq, at } = record;
  if (!count(at) || !count(seq) || seq < 1) return null;
  if (event === 'collector_start') return { event, seq, at };
  if (event === 'collector_end') {
    const { observed, written, dropped, requests, limited, invalid, pending } = record;
    if (![observed, written, dropped, requests, limited, invalid, pending].every(count)) return null;
    return { event, seq, at, observed, written, dropped, requests, limited, invalid, pending };
  }
  const { id, action, status, headersSent, writableFinished } = record;
  if (!['request', 'request_aborted', 'response_finish', 'response_close'].includes(event)
    || !parseId(id) || (action !== 'project' && action !== 'release')
    || !Number.isInteger(status) || status < 0 || status > 999
    || typeof headersSent !== 'boolean' || typeof writableFinished !== 'boolean') return null;
  return { event, seq, at, id, action, status, headersSent, writableFinished };
}

function openDiagnosticFile(env) {
  assertSyntheticFixture(env);
  const fd = fs.openSync(path.join(env.MEDIFLOW_DATA_DIR, 'anydoc-http-diagnostic.jsonl'), 'wx', 0o600);
  return {
    write(record) {
      const metadata = diagnosticMetadata(record);
      if (!metadata) return false;
      const bytes = Buffer.from(`${JSON.stringify(metadata)}\n`);
      let offset = 0;
      while (offset < bytes.length) {
        const written = fs.writeSync(fd, bytes, offset, bytes.length - offset);
        if (written === 0) throw new Error('ANYDOC_DIAGNOSTIC_SHORT_WRITE');
        offset += written;
      }
      return true;
    },
    close() { fs.closeSync(fd); },
  };
}

function exportDiagnosticFile(env, destination) {
  assertSyntheticFixture(env);
  const source = path.join(env.MEDIFLOW_DATA_DIR, 'anydoc-http-diagnostic.jsonl');
  const stat = fs.lstatSync(source);
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size > MAX_RECORDS * 512 || !path.isAbsolute(destination))
    throw new Error('ANYDOC_HTTP_DIAGNOSTIC_INVALID_ARTIFACT');
  const text = fs.readFileSync(source, 'utf8');
  if (text && !text.endsWith('\n')) throw new Error('ANYDOC_HTTP_DIAGNOSTIC_INVALID_ARTIFACT');
  const lines = text === '' ? [] : text.trimEnd().split('\n');
  if (lines.length > MAX_RECORDS) throw new Error('ANYDOC_HTTP_DIAGNOSTIC_INVALID_ARTIFACT');
  const records = lines.map(line => {
    const record = JSON.parse(line);
    const metadata = diagnosticMetadata(record);
    if (!metadata || Object.keys(record).length !== Object.keys(metadata).length
      || Object.keys(record).some(key => !Object.hasOwn(metadata, key)))
      throw new Error('ANYDOC_HTTP_DIAGNOSTIC_INVALID_ARTIFACT');
    return metadata;
  });
  // An incomplete but schema-valid collection remains useful evidence, never complete.
  const status = { event: 'collection_status', complete: serverComplete(records), retained: records.length };
  fs.writeFileSync(destination, [...records, status].map(record => JSON.stringify(record)).join('\n') + '\n',
    { flag: 'wx', mode: 0o600 });
}

function installHttpDiagnostic(prototype, write) {
  const original = prototype.emit;
  const removers = [];
  let observed = 0, written = 0, dropped = 0, requests = 0, limited = 0, invalid = 0, pending = 0, sealed = false;
  const record = metadata => {
    if (sealed) return;
    const value = { ...metadata, seq: ++observed, at: Date.now() };
    if (observed > MAX_RECORDS - 1) { dropped++; return; }
    try { if (write(value) === false) dropped++; else written++; }
    catch { dropped++; } // Application delivery stays independent of the sink.
  };
  record({ event: 'collector_start' });
  function wrapped(event, ...args) {
    if (event === 'request') {
      const [request, response] = args;
      try {
        const matches = typeof request.url === 'string'
          && /^\/api\/attachments\/[^/?]+\/local-extraction$/u.test(request.url);
        const action = request.method === 'DELETE' ? 'release'
          : request.method === 'POST' && request.headers['x-mediflow-extraction-action'] === 'project' ? 'project' : null;
        const supplied = request.headers?.[HEADER];
        if (matches && action && supplied !== undefined) {
          const parsed = parseId(supplied);
          if (!parsed) invalid++;
          else if (++requests > 128) limited++;
          else {
            pending++;
            const emit = event => record({ event, id: parsed.id, action,
              status: Number.isInteger(response.statusCode) ? response.statusCode : 0,
              headersSent: response.headersSent === true, writableFinished: response.writableFinished === true });
            emit('request');
            const aborted = () => emit('request_aborted');
            const finish = () => emit('response_finish');
            const close = () => { pending--; emit('response_close'); };
            request.once('aborted', aborted); response.once('finish', finish); response.once('close', close);
            removers.push(() => { request.off('aborted', aborted); response.off('finish', finish); response.off('close', close); });
          }
        }
      } catch { invalid++; }
    }
    return Reflect.apply(original, this, [event, ...args]);
  }
  prototype.emit = wrapped;
  return () => {
    if (sealed) return;
    sealed = true;
    if (prototype.emit === wrapped) prototype.emit = original;
    for (const remove of removers) remove();
    try { write({ event: 'collector_end', seq: observed + 1, at: Date.now(),
      observed, written, dropped, requests, limited, invalid, pending }); }
    catch { /* A missing end record makes export explicitly incomplete. */ }
  };
}

module.exports = { assertSyntheticFixture, installHttpDiagnostic, openDiagnosticFile, exportDiagnosticFile };
if (require.main === module) {
  try {
    if (process.argv.length !== 4 || process.argv[2] !== '--export') throw new Error();
    exportDiagnosticFile(process.env, process.argv[3]);
  } catch {
    process.stderr.write('ANYDOC_HTTP_DIAGNOSTIC_EXPORT_FAILED\n');
    process.exitCode = 1;
  }
} else if (process.env.MEDIFLOW_ANYDOC_HTTP_DIAGNOSTIC === '1') {
  const sink = openDiagnosticFile(process.env);
  const stop = installHttpDiagnostic(http.Server.prototype, sink.write);
  // No signal handler: do not replace the application's shutdown behavior.
  // Forced termination/missing exit hook yields an unsealed, incomplete artifact.
  process.once('exit', () => { stop(); sink.close(); });
}
